j.open(0);document.querySelector('#alContinue').click();finishTrainingToTest();while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];if(!q.assessment){a.skip();continue}a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(!j.load().lessons[0].passed||j.load().lessons[0].best!==100)throw Error('Correct test did not pass');document.querySelector('#journeyNext').click();if(a.snapshot().journey.index!==1||!a.snapshot().intro)throw Error('Next lesson broken');
